questionvariables.text:
/* Two arrow diagrams. Records 1 is many-to-many (farmer k delivers to both centres,
   and each centre has several farmers), so not a function; Records 2 is one-to-many,
   not a function. Farmer i goes to centre 1 if i is odd, centre 2 if even, so with
   at least 3 farmers some centre always has two farmers. */
farmers: rand([3, 4, 5]);
k: rand(farmers) + 1;
cpair: rand([["Litein", "Kapkatet"], ["Kapsoit", "Chepseon"], ["Sosiot", "Kipkelion"]]);
c1: first(cpair);
c2: second(cpair);
/* Dropdowns share one option list; values are static atoms. */
ta1: [[isfn, false, "a function"], [notfn, true, "not a function"]];
ta2: [[isfn, false, "a function"], [notfn, true, "not a function"]];
tac1: first(mcq_correct(ta1));
tac2: first(mcq_correct(ta2));
